_np = [['Start every sale by naming the hazard, such as dust, noise above 85 dB, splashes or falling objects, before you name a product, so the customer buys for the risk.', 'Ask three questions first: what task, how long each day, and what the work area is like, and write the answers on the sale note.'], ['Look for the standard number and rating printed on the item itself, not just on the box, and keep a photo of the marking for your records.', 'Compare the marking with the hazard: an item rated for light dust is not suitable for fine hazardous powder, so match class to task.'], ['Ask each supplier for a current test certificate and check the issue date; if it is older than the product design change, request an updated one.', 'Keep a supplier file with certificate, contact, delivery record and any returns, and review it each year to drop unreliable sources.'], ['Let the customer try the item on and move around for two minutes; check for gaps, pressure points and fogging before you accept the sale.', 'Show how to put on, adjust, check and store the item, and give a one-page card so the customer repeats the steps correctly at work.'], ['Say plainly what an item does not protect against, for example that a basic mask does not stop fumes, and recommend the right product or an expert.', 'Never promise total safety; use words like designed to reduce, and refer complex or high-risk jobs to a qualified safety adviser.'], ["Record each batch number against sales so you can contact buyers quickly if a fault is found, and store the record for at least the item's life.", 'Price by comparing cost per use, such as a pair of gloves lasting two weeks against a cheaper pair lasting two days, and show this honestly.'], ['Never sell counterfeit or expired items, and remove any item with damaged packaging or a missing marking from the shelf the same day.', 'Follow the selling rules of your area, keep receipts and warranty terms, and tell the customer how to report faults and return a product.'], ['Run a short checklist at the end of each sale: hazard named, item matched, fit checked, advice given and record saved, then count the completed ones weekly.', 'Review complaints and returns monthly, find the most common cause, and update your advice card or supplier choice to fix it.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]
